package com.bank.jvm;

import java.math.BigDecimal;
import java.util.logging.*;

// Runs a steady trading workload and reports GC pause percentiles.
public class LatencyProbeDemo {
    private static final Logger log = Logger.getLogger(LatencyProbeDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        GcPauseRecorder recorder = new GcPauseRecorder();
        recorder.start();

        OrderMatchingEngine engine = new OrderMatchingEngine();
        log.info("Running steady order-matching workload...");
        engine.run(3_000_000); // steady allocation like live market orders

        Thread.sleep(500); // let final GC notifications arrive
        recorder.report();
    }
}

