class OrderMatchingEngine {
    private volatile long matched = 0;
    void run(int orderCount) {
        BigDecimal px = new BigDecimal("2450.50");
        for (int i = 0; i < orderCount; i++) {
            // each order creates short-lived objects, simulating live order flow
            String sym = (i % 2 == 0) ? "RELIANCE" : "TCS";
            BigDecimal qty = new BigDecimal(100 + (i % 50));
            BigDecimal notional = px.multiply(qty);
            if (notional.signum() > 0) matched++;
        }
    }
    long getMatched() { return matched; }
}

