class GcPauseRecorder {
    private static final Logger log = Logger.getLogger(GcPauseRecorder.class.getName());
    private final java.util.List<Long> pauses = new java.util.concurrent.CopyOnWriteArrayList<>();

    // Subscribe to GC notifications to capture each pause duration in ms.
    void start() {
        for (var gc : java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            if (gc instanceof javax.management.NotificationEmitter emitter) {
                emitter.addNotificationListener((notification, handback) -> {
                    if (com.sun.management.GarbageCollectionNotificationInfo.GARBAGE_COLLECTION_NOTIFICATION
                            .equals(notification.getType())) {
                        var info = com.sun.management.GarbageCollectionNotificationInfo
                                .from((javax.management.openmbean.CompositeData) notification.getUserData());
                        pauses.add(info.getGcInfo().getDuration());
                    }
                }, null, null);
            }
        }
    }

    // Compute and log the P99 pause — the number that matters for latency SLOs.
    void report() {
        if (pauses.isEmpty()) { log.info("No GC pauses recorded"); return; }
        var sorted = new java.util.ArrayList<>(pauses);
        java.util.Collections.sort(sorted);
        long max = sorted.get(sorted.size() - 1);
        long p99 = sorted.get((int) Math.floor(0.99 * (sorted.size() - 1)));
        log.info(String.format("GC pauses: count=%d  P99=%dms  MAX=%dms",
                sorted.size(), p99, max));
        log.info(p99 <= 10 ? "MEETS ultra-low-latency budget (<=10ms)" :
                             "Does NOT meet ultra-low-latency budget");
    }
}
